// =============================================================================
// Lifecycle — SafeCall, Execution, RunExecution
// =============================================================================

// SafeCall wraps fn in a deferred recover() so a handler panic does
// not take down the entire process. Returns fn's error verbatim on
// normal return; converts panics into wrapped errors. *rtk.EarlyExit
// panics are preserved through the error chain so main()'s ExitCode()
// can pick up the requested exit code.
func SafeCall(fn func() error) (err error) {
	defer func() {
		if r := recover(); r != nil {
			if ee, ok := r.(*rtk.EarlyExit); ok {
				err = ee
				return
			}
			err = fmt.Errorf("rotini: handler panicked: %v", r)
		}
	}()
	return fn()
}

// Execution is the unit of dispatch a [Program] runs. It carries the
// matched command path and the closure that, when called, parses
// inputs and invokes the user's handler.
type Execution struct {
	Path string
	Run  func() error
}

// RunExecution invokes ex.Run wrapped in [SafeCall]. Returns
// [ErrEmptyExecution] when ex.Run is nil — a codegen bug rather than
// a user-input error.
func RunExecution(ex Execution) error {
	if ex.Run == nil {
		return ErrEmptyExecution
	}
	return SafeCall(ex.Run)
}

// ErrEmptyExecution indicates an Execution with no Run closure was
// dispatched. Always a generated-code bug.
var ErrEmptyExecution = errors.New("rotini: execution has nil Run closure")

// ErrParserUnbound is returned when an Execution closure runs but no
// Parser service is bound under the "parser" registry key. Always a
// generated-code bug.
var ErrParserUnbound = errors.New("rotini: parser service not bound")

