// =============================================================================
// Program — entrypoint type + NewProgram + Execute auto-binding rtk services
// =============================================================================

// Program is the assembled CLI. Construct via [NewProgram], then call
// [Program.Execute] from main().
type Program struct {
	registry *rtk.Registry
	handlers Handlers
}

// NewProgram returns a Program wired with the supplied Handlers and
// the rtk-default services (IO, OS, Signals, Ticker) bound under the
// well-known keys "io", "os", "signals", "ticker".
func NewProgram(h Handlers) *Program {
	reg := rtk.NewRegistry()
	reg.Bind("io", rtk.NewIO())
	reg.Bind("os", rtk.NewOS())
	reg.Bind("signals", rtk.NewSignals())
	reg.Bind("ticker", rtk.NewTicker())
	return &Program{registry: reg, handlers: h}
}

// Registry returns the program's service registry. Callers can bind
// overrides (e.g., for tests) before calling Execute.
func (p *Program) Registry() *rtk.Registry { return p.registry }

// Execute parses os.Args[1:] and dispatches to the matched command's
// handler. Returns the handler's error verbatim — rtk error types
// such as *EarlyExit propagate through so main()'s ExitCode mapping
// can act on them.
func (p *Program) Execute() error {
	return p.ExecuteArgs(os.Args[1:])
}

// ExecuteArgs is the testable form of [Program.Execute]: argv is
// supplied explicitly so tests don't have to mutate os.Args.
func (p *Program) ExecuteArgs(argv []string) error {
	ros := rtk.Get[rtk.OS](p.registry, "os")
	if ros == nil {
		ros = rtk.NewOS()
	}
	parser := rtk.NewParser(Spec, rtk.Inputs{
		Argv:  argv,
		Stdin: os.Stdin,
		Env:   ros,
	})
	p.registry.Bind("parser", parser)

	tok, err := rtk.Tokenize(argv, Spec)
	if err != nil {
		return err
	}
	path := strings.Join(tok.CommandPath, "-")

	build, ok := executors[path]
	if !ok {
		return errors.New("rotini: no executor for command path " + path)
	}
	return RunExecution(build(p))
}

// =============================================================================
// Completion — per-program accessor wrapping rtk.GenerateCompletion
// =============================================================================

// Completion returns a shell-completion script for the program's
// spec. shell is one of [rtk.SupportedShells]. Returns
// [rtk.ErrUnknownShell] for an unrecognized shell name.
func Completion(shell rtk.Shell) (string, error) {
	return rtk.GenerateCompletion(shell, Spec)
}

// =============================================================================
// Render — RenderError + ExitCode
// =============================================================================

// RenderError writes a human-readable representation of err to w.
// Recognized rtk error types get a brief category prefix so users
// can tell at a glance what kind of failure occurred.
func RenderError(w io.Writer, err error) {
	if w == nil || err == nil {
		return
	}
	prefix := "rotini"
	if prefix == "" {
		prefix = "rotini"
	}

	var (
		unkCmd *rtk.UnknownCommandError
		unkFlg *rtk.UnknownFlagError
		unkArg *rtk.UnknownArgumentError
		missR  *rtk.MissingRequiredError
		coerce *rtk.CoercionError
		valid  *rtk.ValidationError
	)
	switch {
	case errors.As(err, &unkCmd):
		fmt.Fprintf(w, "%s: unknown command: %s\n", prefix, unkCmd.Error())
	case errors.As(err, &unkFlg):
		fmt.Fprintf(w, "%s: unknown flag: %s\n", prefix, unkFlg.Error())
	case errors.As(err, &unkArg):
		fmt.Fprintf(w, "%s: %s\n", prefix, unkArg.Error())
	case errors.As(err, &missR):
		fmt.Fprintf(w, "%s: %s\n", prefix, missR.Error())
	case errors.As(err, &coerce):
		fmt.Fprintf(w, "%s: %s\n", prefix, coerce.Error())
	case errors.As(err, &valid):
		fmt.Fprintf(w, "%s: %s\n", prefix, valid.Error())
	default:
		fmt.Fprintf(w, "%s: %s\n", prefix, err.Error())
	}
}

// ExitCode maps an error to a process exit code suitable for os.Exit.
// nil → 0. *rtk.EarlyExit carries an explicit code through. Anything
// else returns 1.
func ExitCode(err error) int {
	if err == nil {
		return 0
	}
	var ee *rtk.EarlyExit
	if errors.As(err, &ee) {
		return ee.Code
	}
	return 1
}
